    if (!existing.operation().equals(operation) || !existing.params().equals(params)) {
        throw ApiException.conflict("COMMAND_KEY_REUSED", "相同 commandKey 但参数不同，拒绝重放");
    }
    return fromJson(existing.response(), type);
}

